#!/bin/sh
# Transport/install only. No SUT request, Linux benchmark preflight, or cohort.
set -eu
umask 077
base=/root/t44-r9/independent772
load_rsa_private=/root/t44-r9/r29-load-key-01/load-only-private.pem
if [ -e "$base/runtime" ]; then
  printf '%s\n' 'Private runtime destination already exists; preserving it.' >&2
  exit 2
fi
mkdir -p "$base/public" "$base/results"
chmod 700 "$base" "$base/public" "$base/results"
if [ ! -f "$base/public/runtime.772seal" ]; then
  cat '/root/t44-r9/independent772/public/runtime.b64.part01' '/root/t44-r9/independent772/public/runtime.b64.part02' '/root/t44-r9/independent772/public/runtime.b64.part03' '/root/t44-r9/independent772/public/runtime.b64.part04' '/root/t44-r9/independent772/public/runtime.b64.part05' '/root/t44-r9/independent772/public/runtime.b64.part06' | base64 -d > "$base/public/runtime.772seal"
fi
base64 -d > "$base/public/capsule-key.rsa-oaep-sha256" <<'PUBLIC_OR_OPAQUE_capsule_key_rsa_oaep_sha256'

PUBLIC_OR_OPAQUE_capsule_key_rsa_oaep_sha256
base64 -d > "$base/public/bootstrap.py" <<'PUBLIC_OR_OPAQUE_bootstrap_py'

PUBLIC_OR_OPAQUE_bootstrap_py
base64 -d > "$base/public/launch.py" <<'PUBLIC_OR_OPAQUE_launch_py'

PUBLIC_OR_OPAQUE_launch_py
printf '%s  %s\n' \
  '79edc21c71556ccdaeb5c591e772195f2df5764fcee37420affc5fb8a419165c' "$base/public/runtime.772seal" \
  '878fb5ed4df9ae8246e3c11145ecd4bb1f00a1385b15e1b5f04748506995f690' "$base/public/capsule-key.rsa-oaep-sha256" \
  '09266efde00e382d019365766df68b9f2d78d6e750454aaac76d5e853844bf93' "$base/public/bootstrap.py" \
  'b7cdbafa4ea41f842781189bb56603dfe352ab9367d48cda59af7593387d4f3d' "$base/public/launch.py" | sha256sum -c -
# The private RSA key and the unwrapped capsule key remain only on LOAD.
openssl pkeyutl -decrypt -inkey "$load_rsa_private" \
  -in "$base/public/capsule-key.rsa-oaep-sha256" \
  -out "$base/capsule.key.new" \
  -pkeyopt rsa_padding_mode:oaep \
  -pkeyopt rsa_oaep_md:sha256 \
  -pkeyopt rsa_mgf1_md:sha256
chmod 600 "$base/capsule.key.new"
mv "$base/capsule.key.new" "$base/capsule.key"
docker run --rm --pull=never --network none --cpus 1 --memory 256m --pids-limit 32 \
  --read-only --cap-drop ALL --security-opt no-new-privileges \
  --tmpfs /tmp:rw,nosuid,nodev,size=16m \
  --mount "type=bind,src=$base,dst=/private" \
  --entrypoint python3 \
  sha256:4f3baf081863a4580b5608699d9a7a8af2d89c3e87abbb60089b630b9102b2a1 \
  /private/public/bootstrap.py /private/public/runtime.772seal \
  /private/capsule.key /private/runtime
printf '%s\n' 'Opaque transport and private runtime install complete. SUT NOT RUN; benchmark grant still required.'
